import React, { useState } from 'react';
import { useQuery, useQueryClient } from 'react-query';
import { itemsAPI, categoriesAPI, protectionTypesAPI } from '../services/api';

const AdminDashboard = () => {
  const queryClient = useQueryClient();
  const { data: items = [] } = useQuery('items', () => itemsAPI.getAll().then(res => res.data || []));
  const { data: categories = [] } = useQuery('categories', () => categoriesAPI.getAll().then(res => res.data || []));
  const { data: protectionTypes = [] } = useQuery('protectionTypes', () => protectionTypesAPI.getAll().then(res => res.data || []));

  const [itemForm, setItemForm] = useState({
    name: '',
    productCode: '',
    imageUrl: '',
    specifications: '',
    protectionTypeId: '',
    categoryIds: [],
  });
  const [itemError, setItemError] = useState('');
  const [itemSuccess, setItemSuccess] = useState('');
  const [itemLoading, setItemLoading] = useState(false);

  const handleItemFormChange = (e) => {
    const { name, value, type, selectedOptions } = e.target;
    if (type === 'select-multiple') {
      setItemForm({
        ...itemForm,
        [name]: Array.from(selectedOptions, (option) => option.value),
      });
    } else {
      setItemForm({
        ...itemForm,
        [name]: value,
      });
    }
  };

  const handleAddItem = async (e) => {
    e.preventDefault();
    setItemError('');
    setItemSuccess('');
    setItemLoading(true);
    try {
      const payload = {
        name: itemForm.name,
        productCode: itemForm.productCode,
        imageUrl: itemForm.imageUrl,
        specifications: itemForm.specifications,
        protectionType: { id: Number(itemForm.protectionTypeId) },
        categories: itemForm.categoryIds.map((id) => ({ id: Number(id) })),
      };
      await itemsAPI.create(payload);
      setItemForm({
        name: '',
        productCode: '',
        imageUrl: '',
        specifications: '',
        protectionTypeId: '',
        categoryIds: [],
      });
      setItemSuccess('Item added successfully!');
      queryClient.invalidateQueries('items');
    } catch (err) {
      setItemError('Failed to add item. Please check your input.');
    } finally {
      setItemLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto py-10 space-y-8">
      <div>TEST MESSAGE</div>
      {/* Add Item Form */}
      <div className="card">
        <div className="card-header">
          <h2 className="text-lg font-semibold text-gray-900">Add New Item</h2>
        </div>
        <form className="space-y-4" onSubmit={handleAddItem}>
          {itemError && (
            <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-md">{itemError}</div>
          )}
          {itemSuccess && (
            <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-2 rounded-md">{itemSuccess}</div>
          )}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700">Name</label>
              <input type="text" name="name" value={itemForm.name} onChange={handleItemFormChange} required className="input-field" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Product Code</label>
              <input type="text" name="productCode" value={itemForm.productCode} onChange={handleItemFormChange} required className="input-field" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Image URL</label>
              <input type="text" name="imageUrl" value={itemForm.imageUrl} onChange={handleItemFormChange} className="input-field" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Specifications</label>
              <input type="text" name="specifications" value={itemForm.specifications} onChange={handleItemFormChange} className="input-field" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Protection Type</label>
              <select name="protectionTypeId" value={itemForm.protectionTypeId} onChange={handleItemFormChange} required className="input-field">
                <option value="">Select Protection Type</option>
                {protectionTypes.map((pt) => (
                  <option key={pt.id} value={pt.id}>{pt.name}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Categories</label>
              <select name="categoryIds" value={itemForm.categoryIds} onChange={handleItemFormChange} multiple className="input-field">
                {categories.map((cat) => (
                  <option key={cat.id} value={cat.id}>{cat.name}</option>
                ))}
              </select>
            </div>
          </div>
          <div>
            <button type="submit" disabled={itemLoading} className="btn-primary">
              {itemLoading ? 'Adding...' : 'Add Item'}
            </button>
          </div>
        </form>
      </div>

      {/* Items Table */}
      <div className="card">
        <div className="card-header">
          <h2 className="text-lg font-semibold text-gray-900">Items List</h2>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Name</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Product Code</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Protection Type</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Categories</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {items.map((item) => (
                <tr key={item.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap">{item.name}</td>
                  <td className="px-6 py-4 whitespace-nowrap">{item.productCode}</td>
                  <td className="px-6 py-4 whitespace-nowrap">{item.protectionType?.name || '-'}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {item.categories && item.categories.length > 0
                      ? item.categories.map((cat) => cat.name).join(', ')
                      : '-'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
